def R(p):return list(csv.DictReader(open(p)))
def V(p):return dict(x.split('=',1) for x in Path(p).read_text().splitlines() if '=' in x)
def S(x):return {'median_ms':statistics.median(x),'mean_ms':statistics.mean(x),'min_ms':min(x),'max_ms':max(x),'p25_ms':float(np.percentile(x,25)),'p75_ms':float(np.percentile(x,75))}
def M(a,b):
 d=b.astype('f8')-a.astype('f8');return {'max_abs':float(abs(d).max()),'mean_abs':float(abs(d).mean()),'p99_abs':float(np.percentile(abs(d),99)),'rel_frob':float(np.linalg.norm(d)/max(np.linalg.norm(a.astype('f8')),1e-30))}
def main():
 ap=argparse.ArgumentParser();ap.add_argument('--root',type=Path,required=True);ap.add_argument('--canonical',type=Path,required=True);a=ap.parse_args();root=a.root
 ds={'O4':[root/'o4_a',root/'o4_b'],'O5':[root/'o5_a',root/'o5_b']};runs={m:sum((R(d/'pipeline_runs.csv') for d in q),[]) for m,q in ds.items()};fine={m:[R(p) for d in q for p in sorted(d.glob('derivative_attribution_*.csv'))] for m,q in ds.items()};dispatch={m:[V(p) for d in q for p in sorted(d.glob('dispatch_*.txt'))] for m,q in ds.items()}
 cs={m:S([float(x['compute_ms']) for x in q]) for m,q in runs.items()};ws={m:S([float(x['wall_ms']) for x in q]) for m,q in runs.items()};gemm={m:statistics.median(sum(float(x['gemm_core_ms']) for x in q) for q in fine[m]) for m in ds}
 o4=root/'optimized_stable_p';o5=root/'optimized_stable_p_transposed';names=['stage1_initial_parameters','stage1_final_parameters','pose_initial_parameters','pose_final_parameters','pose_shape_initial_parameters','pose_shape_final_parameters','final_physical_beta'];parity={n:M(np.fromfile(o4/f'{n}.f32','<f4'),np.fromfile(o5/f'{n}.f32','<f4')) for n in names};canon=np.load(a.canonical/'pipeline_reference.npz');cp={n:M(canon[n],np.fromfile(o5/f'{n}.f32','<f4')) for n in names};trajectory=all((o4/f'{s}_trajectory.csv').read_bytes()==(o5/f'{s}_trajectory.csv').read_bytes() for s in ('stage1','pose','pose_shape')) and all(x['max_abs']==0 for x in parity.values())
