 mr=min(runs['O5'],key=lambda x:abs(float(x['compute_ms'])-cs['O5']['median_ms']));stages={s:{'ms':float(mr[f'{s}_ms']),'percent':100*float(mr[f'{s}_ms'])/cs['O5']['median_ms']} for s in ('stage1','pose','pose_shape')};cats={c:sum(float(mr[f'{s}_{z}']) for s in stages) for c,z in [('jacobian','jacobian_ms'),('objective','objective_ms'),('normal_equations','ne_ms'),('solve','solve_ms'),('control','control_ms')]};saving=cs['O4']['median_ms']-cs['O5']['median_ms'];gs=gemm['O4']-gemm['O5'];inc=saving-gs;pct=100*saving/cs['O4']['median_ms'];win='STRONG_SYSTEM_WIN' if pct>=5 else 'WIN' if pct>=2 else 'MARGINAL' if pct>=.5 else 'NEUTRAL' if pct>=-.5 else 'LOSS';approved=trajectory and saving>0 and pct>=2
