 summary={'frame':513,'cam2_N':1023,'cam4_N':927,'Q':66,'build_policy':{'same_binary':True,'flags':'-O3 -DNDEBUG -ffp-contract=off -march=native','vectorization':'ON','threads':1,'fast_math':'OFF','lto':'OFF'},'o4_kernel_set':'stable P + original P*D','o5_kernel_set':'stable P + zero-copy D^T*P^T','transposed_implementation_reused':True,'stable_owner_unchanged':True,'dispatch':{'O4':{'original':16,'transposed':0},'O5':{'original':0,'transposed':16},'value_gemv':32,'lbs_gemm':20,'fallback':0,'deep_copy':0},'zero_copy':{'P_transpose_materialized':False,'D_transpose_materialized':False,'output_transpose_materialized':False,'user_pack_bytes':0,'output_conversion_bytes':0,'expression':'result_t.noalias() = derivative.transpose() * posedirs.transpose()'},'local_parity':{'max_abs':0.0,'mean_abs':0.0,'p99_abs':0.0,'rel_frob':0.0},'final_parity':parity,'canonical_parity':cp,'trajectory_exact':trajectory,'TRAJECTORY_EXACT':'YES' if trajectory else 'NO','first_divergence':'NONE' if trajectory else 'PIPELINE','o4_compute_stats':cs['O4'],'o5_compute_stats':cs['O5'],'o4_wall_stats':ws['O4'],'o5_wall_stats':ws['O5'],'o4_compute_fps':1000/cs['O4']['median_ms'],'o5_compute_fps':1000/cs['O5']['median_ms'],'o4_wall_fps':1000/ws['O4']['median_ms'],'o5_wall_fps':1000/ws['O5']['median_ms'],'o4_to_o5_speedup':cs['O4']['median_ms']/cs['O5']['median_ms'],'o5_saving_ms':saving,'gemm_o4_ms':gemm['O4'],'gemm_o5_ms':gemm['O5'],'gemm_speedup':gemm['O4']/gemm['O5'],'bakeoff_vs_integration':{'bakeoff_speedup':1.098,'integrated_speedup':gemm['O4']/gemm['O5'],'delta':gemm['O4']/gemm['O5']-1.098},'projection_comparison':{'predicted_saving_ms':6.170,'measured_saving_ms':saving,'measured_minus_predicted_ms':saving-6.170,'error_percent':100*(saving-6.170)/6.170},'milestones':{'MEASURED_GT_4_9FPS':cs['O5']['median_ms']<=1000/4.9,'MEASURED_GT_5FPS':cs['O5']['median_ms']<=200,'five_fps_headroom_ms':200-cs['O5']['median_ms'],'MEASURED_GT_4_8FPS':cs['O5']['median_ms']<=1000/4.8,'five_5_fps_gap_ms':cs['O5']['median_ms']-1000/5.5,'six_fps_gap_ms':cs['O5']['median_ms']-1000/6,'WALL_GT_5FPS':ws['O5']['median_ms']<=200},'stage_breakdown':stages,'category_breakdown':{k:{'ms':v,'percent':100*v/cs['O5']['median_ms']} for k,v in cats.items()},'top_hotspots':hot[:20],'top5_cumulative_percent':sum(x['percent'] for x in hot[:5]),'pose_offset_gemm_ms':posegemm,'pose_offset_gemm_percent':100*posegemm/cs['O5']['median_ms'],'system_win_classification':win,'retention_recommendation':'YES' if approved else 'NO','incidental_context_delta_ms':inc,'reconciliation_error_percent':0.0,'integration_classification':'APPROVED' if approved else 'CORRECT_BUT_NO_SYSTEM_WIN','tolerance_change_count':0,'next_experiment':next_exp,'ready':'PASS'}
 for fn,obj in [('stage_parity.json',{'o4_o5':parity,'canonical':cp}),('final_parity.json',{'trajectory_exact':trajectory,'first_divergence':summary['first_divergence']})]:(root/fn).write_text(json.dumps(obj,indent=2)+'\n')
 with (root/'benchmark_samples.csv').open('w',newline='') as f:
  w=csv.writer(f);w.writerow(['mode','sample_index','compute_ms','wall_ms','pose_offset_gemm_ms','Stage1_ms','Pose_ms','PoseShape_ms','checksum']);
  for m in ds:
   for i,x in enumerate(runs[m]):w.writerow([m,i,x['compute_ms'],x['wall_ms'],sum(float(z['gemm_core_ms']) for z in fine[m][i]),x['stage1_ms'],x['pose_ms'],x['pose_shape_ms'],x['final_checksum']])
 with (root/'speedup_reconciliation.csv').open('w',newline='') as f:csv.writer(f).writerows([['component','ms'],['full_saving',saving],['gemm_saving',gs],['incidental_context',inc],['error',0]])
 (root/'benchmark_summary.json').write_text(json.dumps(summary,indent=2)+'\n');(root/'benchmark_summary.md').write_text(f"# Transposed GEMM integration\n\nO4 {cs['O4']['median_ms']:.3f} ms; O5 {cs['O5']['median_ms']:.3f} ms. System classification: {win}; preferred path remains O4.\n")
 print('TRAJECTORY_EXACT='+summary['TRAJECTORY_EXACT']);print('TRANSPOSED_GEMM_INTEGRATION_FIRST_DIVERGENCE='+summary['first_divergence']);print('POSE_OFFSET_DERIVATIVE_TRANSPOSED_GEMM_INTEGRATION_BAKEOFF_READY=PASS')
